import { dirname, join, extname } from 'node:path';
import { timingSafeEqual, createHmac, randomBytes, scryptSync, createCipheriv, createDecipheriv } from 'node:crypto';

const __dirname=dirname(fileURLToPath(import.meta.url));
const html=await readFile(join(__dirname,'index.html'));
const adminHtml=await readFile(join(__dirname,'admin.html'));
const port=Number(process.env.PORT||3000);
const SUPABASE_URL=process.env.SUPABASE_URL||'';
const SUPABASE_KEY=process.env.SUPABASE_KEY||'';
const WORKSPACE_TOKEN=process.env.WORKSPACE_TOKEN||'';
const APP_USERNAME=process.env.APP_USERNAME||'';
const APP_PASSWORD=process.env.APP_PASSWORD||'';
const OPENAI_API_KEY=process.env.OPENAI_API_KEY||'';
const OPENAI_MODEL=process.env.OPENAI_MODEL||'gpt-6-luna';
const SESSION_SECRET=`${APP_PASSWORD}:${WORKSPACE_TOKEN}:humanitarian-concierge-session`;
const SESSION_MAX_AGE=8*60*60;
const MAX_FILE_BYTES=15*1024*1024;
const MAX_AI_FILE_BYTES=12*1024*1024;

function secureEqual(a,b){const aa=Buffer.from(String(a)),bb=Buffer.from(String(b));return aa.length===bb.length&&timingSafeEqual(aa,bb)}
function sign(value){return createHmac('sha256',SESSION_SECRET).update(value).digest('hex')}
function b64(v){return Buffer.from(v).toString('base64url')}
function unb64(v){return Buffer.from(v,'base64url').toString('utf8')}
function parseCookies(req){const out={};for(const part of String(req.headers.cookie||'').split(';')){const i=part.indexOf('=');if(i>0)out[part.slice(0,i).trim()]=decodeURIComponent(part.slice(i+1).trim())}return out}
function makeSession(payload){const body=b64(JSON.stringify({...payload,exp:Math.floor(Date.now()/1000)+SESSION_MAX_AGE}));return `${body}.${sign(body)}`}
function getSession(req){const token=parseCookies(req).concierge_session||'',i=token.lastIndexOf('.');if(i<1)return null;const body=token.slice(0,i),sig=token.slice(i+1);if(!secureEqual(sig,sign(body)))return null;try{const p=JSON.parse(unb64(body));if(!p.exp||p.exp<Math.floor(Date.now()/1000))return null;return p}catch{return null}}
function sessionCookie(token,maxAge=SESSION_MAX_AGE){return `concierge_session=${encodeURIComponent(token)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`}
function json(res,status,data){res.writeHead(status,{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'});res.end(JSON.stringify(data))}
function redirect(res,location,cookie){const h={location,'cache-control':'no-store'};if(cookie)h['set-cookie']=cookie;res.writeHead(303,h);res.end()}
function htmlResponse(res,body){res.writeHead(200,{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-frame-options':'DENY','referrer-policy':'no-referrer','x-content-type-options':'nosniff'});res.end(body)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function clean(v,n=250){return String(v??'').trim().slice(0,n)}
function validEmail(v){return !v||/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v).trim())}
function validUsername(v){return /^[a-zA-Z0-9._-]{3,60}$/.test(String(v||''))}
function hashPassword(password,salt=randomBytes(16).toString('hex')){return {salt,hash:scryptSync(String(password),salt,64).toString('hex')}}
function verifyPassword(password,salt,expected){if(!salt||!expected)return false;try{return secureEqual(scryptSync(String(password),salt,64).toString('hex'),expected)}catch{return false}}
function now(){return new Date().toISOString()}

const authCss=`:root{--navy:#0d2c3b;--blue:#0f6c8e;--ink:#13232d;--muted:#687984;--line:#dbe5e9;--bg:#f3f7f9;--bad:#9d2d23;--good:#28704a}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 15% 10%,#e5f2f7,transparent 35%),var(--bg);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:var(--ink)}.wrap{width:min(430px,100%)}.brand{margin-bottom:18px}.brand small{color:#557684;font-size:10px;letter-spacing:.14em;text-transform:uppercase;font-weight:850}.brand h1{margin:4px 0 0;font-size:28px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:26px;box-shadow:0 18px 55px rgba(13,44,59,.08)}label{display:block;font-weight:750;margin:14px 0 6px}input{width:100%;padding:12px 13px;border:1px solid #cbd8de;border-radius:10px;font:inherit;outline:none}input:focus{border-color:var(--blue);box-shadow:0 0 0 3px #0f6c8e18}.btn{width:100%;border:0;border-radius:10px;padding:12px 15px;margin-top:18px;background:var(--blue);color:#fff;font-weight:850;font:inherit;cursor:pointer}.note{font-size:12px;color:var(--muted);margin-top:14px}.error{background:#fdecea;color:var(--bad);padding:10px 12px;border-radius:9px;margin:12px 0}.success{background:#e9f6ee;color:var(--good);padding:10px 12px;border-radius:9px;margin:12px 0}.link{display:inline-block;margin-top:12px;color:var(--blue);font-weight:750;text-decoration:none}`;
function authShell(title,content){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>${esc(title)} · Humanitarian Operations Concierge</title><style>${authCss}</style></head><body><div class="wrap"><div class="brand"><small>Humanitarian workflow automation</small><h1>Operations Concierge</h1></div>${content}</div></body></html>`}
function loginPage(error=''){return authShell('Login',`<form class="card" method="post" action="/login"><h2 style="margin:0 0 4px">Sign in</h2><div style="color:var(--muted)">Your workspace is private to your account and evidence sources.</div>${error?`<div class="error">${esc(error)}</div>`:''}<label>Username or email</label><input name="username" autocomplete="username" required autofocus><label>Password</label><input type="password" name="password" autocomplete="current-password" required><button class="btn">Log in</button><a class="link" href="/forgot-password">Forgot password?</a><div class="note">Password resets require administrator approval.</div></form>`)}
function forgotPage(status=''){return authShell('Password help',`<form class="card" method="post" action="/forgot-password"><h2 style="margin:0 0 4px">Request password reset</h2><div style="color:var(--muted)">Enter your username or account email. An administrator will approve the reset and issue a temporary password.</div>${status?`<div class="success">${esc(status)}</div>`:''}<label>Username or email</label><input name="username" autocomplete="username" required autofocus><button class="btn">Request reset</button><a class="link" href="/login">Back to login</a></form>`)}
function changePasswordPage(error=''){return authShell('Change password',`<form class="card" method="post" action="/change-password"><h2 style="margin:0 0 4px">Create your private password</h2><div style="color:var(--muted)">Your temporary password was accepted. Choose a new password before entering your workspace.</div>${error?`<div class="error">${esc(error)}</div>`:''}<label>New password</label><input type="password" name="password" minlength="8" autocomplete="new-password" required autofocus><label>Confirm password</label><input type="password" name="confirm" minlength="8" autocomplete="new-password" required><button class="btn">Save new password</button><div class="note">The administrator cannot see your new password.</div></form>`)}

async function readText(req,max=50000){let raw='';for await(const chunk of req){raw+=chunk;if(raw.length>max)throw new Error('body too large')}return raw}
async function readBody(req){const raw=await readText(req);return raw?JSON.parse(raw):{}}
async function readBuffer(req,maxBytes=MAX_FILE_BYTES){const chunks=[];let total=0;for await(const chunk of req){total+=chunk.length;if(total>maxBytes)throw Object.assign(new Error('file too large'),{statusCode:413});chunks.push(chunk)}return Buffer.concat(chunks)}
async function sb(path,options={}){if(!SUPABASE_URL||!SUPABASE_KEY||!WORKSPACE_TOKEN)throw new Error('Data store is not configured');const r=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,{...options,headers:{apikey:SUPABASE_KEY,authorization:`Bearer ${SUPABASE_KEY}`,'x-workspace-token':WORKSPACE_TOKEN,'content-type':'application/json',accept:'application/json',...(options.headers||{})}});const text=await r.text();let data=null;try{data=text?JSON.parse(text):null}catch{data=text}if(!r.ok)throw new Error(typeof data==='string'?data:(data?.message||`Supabase ${r.status}`));return data}
function categoryFor(name,mime=''){const ext=extname(name||'').toLowerCase();if(ext==='.xlsx'||ext==='.xls'||ext==='.csv')return'Data / Finance';if(ext==='.pptx'||ext==='.ppt')return'Presentation';if(ext==='.jpg'||ext==='.jpeg'||ext==='.png'||ext==='.webp'||mime.startsWith('image/'))return'Photo / Evidence';if(ext==='.pdf')return'PDF / Report';if(ext==='.docx'||ext==='.doc'||ext==='.txt'||ext==='.rtf')return'Document / Report';return'Project Document'}
function safeFileName(name){return String(name||'project-document').replace(/[\r\n\0]/g,' ').trim().slice(0,220)||'project-document'}
function requireSession(req,res,url){const s=getSession(req);if(!s){if(url.pathname.startsWith('/api/'))json(res,401,{ok:false,error:'Authentication required'});else redirect(res,'/login');return null}return s}
function requireAdmin(req,res,url){const s=requireSession(req,res,url);if(!s)return null;if(s.role!=='admin'){if(url.pathname.startsWith('/api/'))json(res,403,{ok:false,error:'Administrator access required'});else redirect(res,'/');return null}return s}
function requireWorker(req,res,url){const s=requireSession(req,res,url);if(!s)return null;if(s.role==='admin'){if(url.pathname.startsWith('/api/'))json(res,403,{ok:false,error:'Worker workspace required'});else redirect(res,'/admin');return null}if(s.must_change){if(url.pathname.startsWith('/api/'))json(res,403,{ok:false,error:'Password change required'});else redirect(res,'/change-password');return null}return s}

function inferActionType(item){const text=`${item.title||''} ${item.summary||''} ${item.email_snippet||''}`.toLowerCase();if(item.status==='watch'||!(item.needs_user))return'no_action';if(/report|sitrep|assessment|inception|narrative|proposal|briefing note/.test(text))return'generate_report';if(/review|comment|feedback|check document|track changes/.test(text))return'review_document';if(/meeting|brief|prepare for|talking points/.test(text))return'prepare_brief';if(/tracker|spreadsheet|update data|update sheet/.test(text))return'update_tracker';if(/summari[sz]e|summary|thread/.test(text))return'summarize_thread';if(/reply|respond|response|confirm|acknowledge|email back|send feedback/.test(text))return'draft_response';if(/clarif|missing information|need more/.test(text))return'clarify';return item.action_type&&item.action_type!=='follow_up'?item.action_type:'draft_response'}
function actionLabel(type){return({draft_response:'Draft response',generate_report:'Do the work',review_document:'Review document',prepare_brief:'Prepare brief',update_tracker:'Update tracker',summarize_thread:'Summarize thread',clarify:'Clarify',follow_up:'Draft follow-up',no_action:'No action'})[type]||'Do the work'}
function productTypeFor(type){return({draft_response:'email',generate_report:'report',review_document:'review',prepare_brief:'brief',update_tracker:'tracker',summarize_thread:'summary',clarify:'other',follow_up:'email'})[type]||'other'}
function evidenceRank(type){return({signed_document:1,approved_report:2,email:3,memory:4,project_document:5,task_document:6,web:7})[type]||7}
function fmtArray(v){return Array.isArray(v)?v:[]}
async function audit(user_id,event_type,{item_id=null,work_product_id=null,details={}}={}){try{await sb('concierge_audit_log',{method:'POST',body:JSON.stringify({user_id,item_id,work_product_id,event_type,details})})}catch(e){console.error('audit',e.message)}}
function outputText(resp){for(const item of resp?.output||[])if(item.type==='message')for(const c of item.content||[])if(c.type==='output_text'&&c.text)return c.text;return resp?.output_text||''}
function webAnnotations(resp){const rows=[];for(const item of resp?.output||[])if(item.type==='message')for(const c of item.content||[])for(const a of c.annotations||[]){const u=a.url||a.url_citation?.url||a.web_citation?.url;if(u)rows.push({url:u,title:a.title||a.url_citation?.title||a.web_citation?.title||u})}return[...new Map(rows.map(x=>[x.url,x])).values()]}
function parseModelJson(text){const raw=String(text||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');try{return JSON.parse(raw)}catch{const s=raw.indexOf('{'),e=raw.lastIndexOf('}');if(s>=0&&e>s)try{return JSON.parse(raw.slice(s,e+1))}catch{}return{body:raw}}}
async function openaiResponse({developer,userContent,files=[],webSearch=false,maxOutput=7000}){if(!OPENAI_API_KEY)return null;const content=[{type:'input_text',text:userContent}];let total=0;for(const f of files){const n=Number(f.size_bytes||0);if(!f.content_base64||!n||total+n>MAX_AI_FILE_BYTES)continue;total+=n;content.push({type:'input_file',filename:f.file_name,file_data:f.content_base64})}const payload={model:OPENAI_MODEL,input:[{role:'developer',content:[{type:'input_text',text:developer}]},{role:'user',content}],max_output_tokens:maxOutput};if(webSearch)payload.tools=[{type:'web_search'}];const r=await fetch('https://api.openai.com/v1/responses',{method:'POST',headers:{authorization:`Bearer ${OPENAI_API_KEY}`,'content-type':'application/json'},body:JSON.stringify(payload)});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data?.error?.message||`OpenAI ${r.status}`);return data}
function deterministicSeed(item,reports,memory){const type=inferActionType(item),pType=productTypeFor(type);if(pType==='email')return{product_type:'email',title:`Draft response — ${item.title}`,subject:item.title?.startsWith('Re:')?item.title:`Re: ${item.title}`,body:`Dear Colleague,\n\nThank you for your email regarding ${item.title||'the matter below'}.\n\nI have reviewed the request. ${item.summary||item.email_snippet||''}\n\nI will follow up with the required information/action. Please let me know if there is anything else you would like included.\n\nKind regards,`,missing_information:fmtArray(item.missing_information),generation_notes:'Fallback draft generated without the AI engine.'};const r=(reports||[])[0];if(r){const bullets=x=>fmtArray(x).map((v,i)=>`${i+1}. ${typeof v==='string'?v:v.detail||JSON.stringify(v)}`).join('\n');return{product_type:pType,title:r.title||item.title,subject:null,body:`EXECUTIVE SUMMARY\n${r.executive_summary||''}\n\nREVIEW OUTCOME\n${r.review_outcome||''}\n\nSTRENGTHS\n${bullets(r.strengths)}\n\nGAPS / ISSUES\n${bullets(r.gaps)}\n\nRECOMMENDATIONS\n${bullets(r.recommendations)}\n\nEVIDENCE\n${bullets(r.evidence)}`,missing_information:fmtArray(item.missing_information),generation_notes:'Existing verified work product reused because the AI engine is not configured.'}}return{product_type:pType,title:item.title||'Work product',subject:null,body:`DRAFT WORK PRODUCT\n\nRequest\n${item.summary||item.email_snippet||''}\n\nVerified project context\n${(memory||[]).slice(0,8).map(m=>`• ${m.workstream}: ${m.current_state}`).join('\n')||'No structured memory is available yet.'}`,missing_information:fmtArray(item.missing_information),generation_notes:'Fallback draft generated without the AI engine.'}}
function generationInstructions(actionType){return`You are the work-execution engine for a humanitarian operations concierge. Complete the requested work, do not merely summarize it. Evidence hierarchy: 1 signed/contractual documents, 2 approved reports, 3 verified email/thread evidence, 4 Operations Memory, 5 project documents, 6 task attachments, 7 public web. If sources conflict, flag the conflict. Never invent names, dates, beneficiary figures, budgets, deadlines, approvals, or completion status. If information is missing, complete what can safely be completed and list what is missing. For email drafts use official professional email practice. For reports use clear headings, evidence-based language, explicit limitations, and actionable recommendations. Current work type: ${actionType}. Return JSON only: {"title":"...","subject":null or "...","body":"full finished work product","assistant_message":"brief note","missing_information":["..."],"evidence_conflicts":["..."]}.`}
// Worker setup helpers. Module scope so gatherContext() can use them.
async function conciergeWorkerConfig(workerId){
  const rows=await sb(`concierge_worker_configs?select=worker_user_id,setup_profile_id,setup_version,config,status,applied_at,updated_at&worker_user_id=eq.${workerId}&status=eq.active&limit=1`);
  return (rows||[])[0]||null;
}
function conciergeEnabledModuleIds(config){return new Set((config?.modules||[]).filter(x=>x&&x.enabled).map(x=>String(x.id||'')))}
function conciergeModuleEnabled(config,id){const mods=config?.modules||[];if(!mods.length)return ['home','operations_memory','history'].includes(id);return mods.some(x=>x&&x.id===id&&x.enabled)}
async function gatherContext(uid,itemId){
  const itemRows=await sb(`fsl_concierge_items?select=*&id=eq.${itemId}&user_id=eq.${uid}&limit=1`),item=(itemRows||[])[0]||null;
  if(!item)return{item:null,memory:[],reports:[],projectDocs:[],taskDocs:[]};
  const applied=await conciergeWorkerConfig(uid),config=applied?.config||{},projectEnabled=conciergeModuleEnabled(config,'projects'),useDocs=conciergeModuleEnabled(config,'documents'),useReports=conciergeModuleEnabled(config,'reports');
  const projectFilter=projectEnabled&&item.project_id?`project_id=eq.${item.project_id}`:'project_id=is.null';
  const[memory,reports,projectDocs,taskDocs]=await Promise.all([
    sb(`fsl_concierge_memory?select=*&user_id=eq.${uid}&${projectFilter}&order=updated_at.desc&limit=20`),
    useReports?sb(`fsl_concierge_reports?select=*&user_id=eq.${uid}&${projectFilter}&order=updated_at.desc&limit=5`):Promise.resolve([]),
    useDocs?sb(`fsl_concierge_documents?select=id,project_id,file_name,mime_type,size_bytes,content_base64,category,description,created_at&user_id=eq.${uid}&${projectFilter}&status=eq.available&order=created_at.desc&limit=8`):Promise.resolve([]),
    useDocs?sb(`concierge_task_documents?select=*&user_id=eq.${uid}&item_id=eq.${itemId}&status=eq.available&order=created_at.desc&limit=8`):Promise.resolve([])
  ]);
  return{item,memory:memory||[],reports:reports||[],projectDocs:projectDocs||[],taskDocs:taskDocs||[],setupConfig:config}
}
function contextText(ctx,actionType){const item=ctx.item||{};return`WORK REQUEST\nAction type: ${actionType}\nTitle: ${item.title||''}\nSender: ${item.sender||''}\nEmail snippet: ${item.email_snippet||item.summary||''}\nThread context: ${item.thread_context_summary||item.summary||''}\nExplicit deadline: ${item.due_at||'none found'}\nKnown missing information: ${JSON.stringify(item.missing_information||[])}\n\nOPERATIONS MEMORY\n${ctx.memory.map(m=>`- ${m.workstream}: ${m.current_state} | owner: ${m.owner||'unknown'} | next date: ${m.next_date||'none'}`).join('\n')||'No structured memory.'}\n\nPROJECT DOCUMENTS\n${ctx.projectDocs.map(d=>`- ${d.file_name} (${d.category||d.mime_type})`).join('\n')||'None.'}\n\nTASK DOCUMENTS\n${ctx.taskDocs.map(d=>`- ${d.file_name} [scope=${d.scope}]`).join('\n')||'None.'}\n\nComplete the work using only supported facts.`}
async function recordEvidence(uid,workProductId,ctx,resp){const rows=[],item=ctx.item;if(item)rows.push({user_id:uid,work_product_id:workProductId,evidence_type:'email',evidence_ref:item.source_message_id||item.id,title:item.title||'Source email',excerpt:item.email_snippet||item.summary||null,url:item.source_url||null,authority_rank:3,metadata:{thread_id:item.source_thread_id||null}});for(const m of ctx.memory.slice(0,12))rows.push({user_id:uid,work_product_id:workProductId,evidence_type:'memory',evidence_ref:m.id,title:m.workstream,excerpt:m.current_state,url:null,authority_rank:4,metadata:{owner:m.owner,next_date:m.next_date}});for(const d of ctx.projectDocs.slice(0,8))rows.push({user_id:uid,work_product_id:workProductId,evidence_type:'project_document',evidence_ref:d.id,title:d.file_name,excerpt:d.description||d.category||null,url:null,authority_rank:5,metadata:{mime_type:d.mime_type,size_bytes:d.size_bytes}});for(const d of ctx.taskDocs.slice(0,8))rows.push({user_id:uid,work_product_id:workProductId,evidence_type:'task_document',evidence_ref:d.id,title:d.file_name,excerpt:`Task attachment · scope ${d.scope}`,url:null,authority_rank:6,metadata:{mime_type:d.mime_type,size_bytes:d.size_bytes}});for(const a of webAnnotations(resp))rows.push({user_id:uid,work_product_id:workProductId,evidence_type:'web',evidence_ref:a.url,title:a.title,excerpt:'Public web source used by the AI work engine.',url:a.url,authority_rank:7,metadata:{}});if(rows.length)await sb('concierge_work_product_evidence',{method:'POST',body:JSON.stringify(rows)})}
async function getWorkProductBundle(uid,id){const[products,versions,messages,evidence,taskDocs]=await Promise.all([sb(`concierge_work_products?select=*&id=eq.${id}&user_id=eq.${uid}&limit=1`),sb(`concierge_work_product_versions?select=*&work_product_id=eq.${id}&user_id=eq.${uid}&order=version.desc`),sb(`concierge_work_product_messages?select=*&work_product_id=eq.${id}&user_id=eq.${uid}&order=created_at.asc`),sb(`concierge_work_product_evidence?select=*&work_product_id=eq.${id}&user_id=eq.${uid}&order=authority_rank.asc,created_at.asc`),sb(`concierge_task_documents?select=id,item_id,work_product_id,file_name,mime_type,size_bytes,scope,status,created_at&work_product_id=eq.${id}&user_id=eq.${uid}&status=eq.available&order=created_at.desc`)]);return{product:(products||[])[0]||null,versions:versions||[],messages:messages||[],evidence:evidence||[],taskDocuments:taskDocs||[]}}
async function learnPreference(uid,message){const text=String(message||'').toLowerCase(),hints={};if(/shorter|concise|brief/.test(text))hints.length='concise';if(/formal|official/.test(text))hints.tone='formal';if(/warmer|friendly/.test(text))hints.tone='warm_professional';if(/bullet|bullets/.test(text))hints.format='bullets';if(!Object.keys(hints).length)return;const rows=await sb(`concierge_user_preferences?select=*&user_id=eq.${uid}&limit=1`),current=(rows||[])[0],learned={...(current?.learned_preferences||{}),...hints,last_revision_instruction:clean(message,500),last_revision_at:now()};await sb('concierge_user_preferences',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:uid,email_tone:current?.email_tone||'professional',report_style:current?.report_style||'concise_evidence_based',default_web_search:Boolean(current?.default_web_search),learned_preferences:learned,updated_at:now()})})}

// --- Universal source-of-truth email sync engine ---
const GOOGLE_CLIENT_ID=process.env.GOOGLE_CLIENT_ID||'';
const GOOGLE_CLIENT_SECRET=process.env.GOOGLE_CLIENT_SECRET||'';
const COMPOSIO_API_KEY=process.env.COMPOSIO_API_KEY||'';
const MICROSOFT_CLIENT_ID=process.env.MICROSOFT_CLIENT_ID||'';
const MICROSOFT_CLIENT_SECRET=process.env.MICROSOFT_CLIENT_SECRET||'';
const OAUTH_TOKEN_SECRET=process.env.OAUTH_TOKEN_SECRET||'';
const SOURCE_SYNC_INTERVAL_MS=Math.max(60000,Number(process.env.SOURCE_SYNC_INTERVAL_MS||120000));
const SOURCE_INITIAL_DAYS=30;
const SOURCE_INITIAL_LIMIT=25;
const SOURCE_JEV_KEY=process.env.JEV_API_KEY||'';
const SOURCE_JEV_MODEL=process.env.JEV_MODEL||'jev-latest';

function sourcePublicBase(){const host=process.env.RAILWAY_PUBLIC_DOMAIN||process.env.RAILWAY_STATIC_URL||'';return host?(/^https?:\/\//.test(host)?host:`https://${host}`):''}
function sourceRedirectUri(provider){return `${sourcePublicBase()}/api/email-oauth/${provider}/callback`}
