function sourceComposioRef(account){const v=String(account?.connection_ref||'');return v.startsWith('composio:')?v.slice('composio:'.length):''}
function sourceAccountConfigured(account){return sourceComposioRef(account)?Boolean(COMPOSIO_API_KEY):sourceOAuthConfigured(account.provider)}
function sourceComposioError(d,status,fallback){const raw=d?.error?.message||d?.error||d?.message||fallback||`Composio request failed (${status})`;return typeof raw==='string'?raw:JSON.stringify(raw)}
async function sourceComposioRequest(path,{method='GET',body}={}){if(!COMPOSIO_API_KEY)throw new Error('Composio API key is not configured');const r=await fetch(`https://backend.composio.dev${path}`,{method,headers:{'x-api-key':COMPOSIO_API_KEY,accept:'application/json',...(body?{'content-type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(sourceComposioError(d,r.status)),{statusCode:r.status,composio:d});return d}
const sourceComposioUserCache=new Map();
async function sourceComposioGetAccount(connectedAccountId){const d=await sourceComposioRequest(`/api/v3.1/connected_accounts/${encodeURIComponent(connectedAccountId)}`);const x=d?.connected_account||d?.item||d?.data||d;if(x?.user_id)sourceComposioUserCache.set(connectedAccountId,String(x.user_id));return x}
async function sourceComposioUserId(connectedAccountId){if(sourceComposioUserCache.has(connectedAccountId))return sourceComposioUserCache.get(connectedAccountId);const x=await sourceComposioGetAccount(connectedAccountId);const userId=String(x?.user_id||'').trim();if(!userId)throw new Error('Composio connected account is missing its user ID');sourceComposioUserCache.set(connectedAccountId,userId);return userId}
async function sourceComposioExecuteKnown(toolSlug,connectedAccountId,userId,args){const r=await fetch(`https://backend.composio.dev/api/v3.1/tools/execute/${encodeURIComponent(toolSlug)}`,{method:'POST',headers:{'x-api-key':COMPOSIO_API_KEY,'content-type':'application/json',accept:'application/json'},body:JSON.stringify({connected_account_id:connectedAccountId,user_id:userId,version:'latest',arguments:args})});const d=await r.json().catch(()=>({}));if(!r.ok||d?.successful===false)throw new Error(sourceComposioError(d,r.status,`Composio ${toolSlug} failed (${r.status})`));return d?.data?.data??d?.data??d}
async function sourceComposioExecute(toolSlug,connectedAccountId,args){const userId=await sourceComposioUserId(connectedAccountId);return sourceComposioExecuteKnown(toolSlug,connectedAccountId,userId,args)}
async function sourceComposioListGmailAccounts(){const q=new URLSearchParams();q.append('toolkit_slugs','gmail');q.append('statuses','ACTIVE');q.set('limit','100');const d=await sourceComposioRequest(`/api/v3.1/connected_accounts?${q.toString()}`);return Array.isArray(d?.items)?d.items:[]}
async function sourceComposioProfile(candidate){const id=String(candidate?.id||'').trim(),userId=String(candidate?.user_id||'').trim();if(!id||!userId)return null;try{const p=await sourceComposioExecuteKnown('GMAIL_GET_PROFILE',id,userId,{user_id:'me'});return{candidate,email:String(p?.emailAddress||p?.email_address||'').trim().toLowerCase(),profile:p}}catch{return null}}
async function sourceComposioResolveAccount(account){const target=String(account?.account_email||'').trim().toLowerCase();if(!target)throw new Error('Mailbox email address is missing');const currentId=sourceComposioRef(account);if(currentId){try{const current=await sourceComposioGetAccount(currentId);if(String(current?.status||'').toUpperCase()==='ACTIVE'){const p=await sourceComposioProfile(current);if(p?.email===target)return{connectedAccountId:currentId,userId:String(current.user_id),profile:p.profile}}}catch(e){if(Number(e?.statusCode)!==404&&Number(e?.statusCode)!==400)throw e}}
  const candidates=await sourceComposioListGmailAccounts();for(const candidate of candidates){const p=await sourceComposioProfile(candidate);if(p?.email!==target)continue;const id=String(candidate.id),userId=String(candidate.user_id);sourceComposioUserCache.set(id,userId);await sb(`humanitarian_email_accounts?id=eq.${account.id}&user_id=eq.${account.user_id}`,{method:'PATCH',body:JSON.stringify({connection_ref:`composio:${id}`,status:'connected',sync_error:null,updated_at:now()})});account.connection_ref=`composio:${id}`;account.status='connected';return{connectedAccountId:id,userId,profile:p.profile}}
  throw Object.assign(new Error(`No active Composio Gmail connection for ${target} exists in this project. Use Reconnect once to authorize it.`),{code:'COMPOSIO_RECONNECT_REQUIRED'})}
async function sourceComposioAuthConfig(){const q=new URLSearchParams({toolkit_slug:'gmail',is_composio_managed:'true',show_disabled:'false',limit:'200'});const d=await sourceComposioRequest(`/api/v3.1/auth_configs?${q.toString()}`);let cfg=(d?.items||[]).find(x=>String(x?.status||'').toUpperCase()==='ENABLED'&&x?.is_composio_managed!==false);if(cfg)return cfg;try{cfg=await sourceComposioRequest('/api/v3.1/auth_configs',{method:'POST',body:{toolkit:{slug:'gmail'}}});return cfg?.auth_config||cfg?.data||cfg}catch(e){throw new Error(/permission|scope|access|forbidden/i.test(String(e.message||''))?'Composio reconnect needs Auth configs Read/Write and Connected accounts Read/Write permissions on this project API key.':String(e.message||'Could not create Gmail auth config'))}}
async function sourceComposioCreateConnectLink(account){let cfg;try{cfg=await sourceComposioAuthConfig()}catch(e){throw e}const authConfigId=String(cfg?.id||'').trim();if(!authConfigId)throw new Error('No Gmail auth configuration is available in this Composio project');const callback=`${sourcePublicBase()}/api/email-accounts/${account.id}/composio/callback`;let d;try{d=await sourceComposioRequest('/api/v3.1/connected_accounts/link',{method:'POST',body:{auth_config_id:authConfigId,user_id:String(account.user_id),callback_url:callback}})}catch(e){throw new Error(/permission|scope|access|forbidden/i.test(String(e.message||''))?'Composio reconnect needs Connected accounts Read/Write permission on this project API key.':String(e.message||'Could not create Composio Gmail connection'))}const connectedAccountId=String(d?.connected_account_id||'').trim(),redirectUrl=String(d?.redirect_url||'').trim();if(!connectedAccountId||!redirectUrl)throw new Error('Composio did not return a valid Gmail authorization link');await sb(`humanitarian_email_accounts?id=eq.${account.id}&user_id=eq.${account.user_id}`,{method:'PATCH',body:JSON.stringify({connection_ref:`composio:${connectedAccountId}`,status:'pending',sync_error:null,last_sync_started_at:null,last_sync_completed_at:null,updated_at:now()})});return{connectedAccountId,redirectUrl}}
async function sourceComposioGmailMessages(account){const resolved=await sourceComposioResolveAccount(account),connectedAccountId=resolved.connectedAccountId;let query=`newer_than:${SOURCE_INITIAL_DAYS}d`;if(account.last_sync_at){const d=new Date(account.last_sync_at);if(Number.isFinite(d.getTime()))query=`after:${d.getUTCFullYear()}/${String(d.getUTCMonth()+1).padStart(2,'0')}/${String(d.getUTCDate()).padStart(2,'0')}`}const listed=await sourceComposioExecuteKnown('GMAIL_FETCH_EMAILS',connectedAccountId,resolved.userId,{user_id:'me',query,label_ids:['INBOX'],max_results:25,include_payload:false,verbose:false,ids_only:false,include_spam_trash:false}),rows=listed?.messages||[];const messages=[];for(const row of rows.slice(0,25)){const mid=row?.messageId||row?.id;if(!mid)continue;let full={};try{full=await sourceComposioExecuteKnown('GMAIL_FETCH_MESSAGE_BY_MESSAGE_ID',connectedAccountId,resolved.userId,{user_id:'me',message_id:mid,format:'full'})}catch{full=row}const m=full?.message||full||row,headers=m?.payload?.headers||[],fromRaw=sourceHeader(headers,'From')||m?.sender||row?.sender||'',from=sourceParseSender(fromRaw),date=sourceHeader(headers,'Date'),received=Number(m?.internalDate)?new Date(Number(m.internalDate)).toISOString():(m?.messageTimestamp||row?.messageTimestamp||(Number.isFinite(Date.parse(date))?new Date(date).toISOString():now())),body=sourceStripHtml(sourceGmailBody(m?.payload)||m?.messageText||m?.snippet||row?.messageText||row?.preview?.body||'');messages.push({provider_message_id:mid,provider_thread_id:m?.threadId||row?.threadId||null,subject:sourceHeader(headers,'Subject')||m?.subject||row?.subject||row?.preview?.subject||'(No subject)',sender_name:from.name,sender_email:from.email,received_at:received,body_text:body,source_url:m?.display_url||row?.display_url||`https://mail.google.com/mail/u/0/#all/${mid}`,raw_metadata:{labelIds:m?.labelIds||row?.labelIds||[],composio:true,connected_account_id:connectedAccountId}})}return{messages,cursor:null,connectedAccountId}}
async function sourceSyncComposioAccount(account){const started=now();let run=null;try{const rr=await sb('concierge_email_sync_runs',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({user_id:account.user_id,account_id:account.id,provider:account.provider,status:'running',started_at:started})});run=(rr||[])[0]||null;await sb(`humanitarian_email_accounts?id=eq.${account.id}`,{method:'PATCH',body:JSON.stringify({last_sync_started_at:started,sync_error:null,updated_at:started})});if(account.provider!=='gmail')throw new Error('Composio sync currently supports Gmail accounts only');const batch=await sourceComposioGmailMessages(account);let created=0;for(const m of batch.messages||[]){const x=await sourceIngestMessage(account.user_id,account,m);if(x.created)created++}const done=now(),total=Number(account.messages_processed||0)+created;await sb(`humanitarian_email_accounts?id=eq.${account.id}`,{method:'PATCH',body:JSON.stringify({connection_ref:`composio:${batch.connectedAccountId}`,status:'connected',last_sync_at:done,last_sync_completed_at:done,sync_error:null,messages_processed:total,updated_at:done})});await sb('fsl_concierge_sync_state',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({id:`composio:${account.id}`,user_id:account.user_id,mailbox:account.account_email,last_history_id:null,last_sync_at:done,sync_mode:'read_only',updated_at:done})});if(run)await sb(`concierge_email_sync_runs?id=eq.${run.id}`,{method:'PATCH',body:JSON.stringify({status:'success',completed_at:done,messages_seen:(batch.messages||[]).length,messages_created:created})});return{ok:true,account_id:account.id,seen:(batch.messages||[]).length,created,last_sync_at:done,transport:'composio'}}catch(e){const done=now(),msg=clean(e.message,1000);await sb(`humanitarian_email_accounts?id=eq.${account.id}`,{method:'PATCH',body:JSON.stringify({status:'error',sync_error:msg,last_sync_completed_at:done,updated_at:done})}).catch(()=>{});if(run)await sb(`concierge_email_sync_runs?id=eq.${run.id}`,{method:'PATCH',body:JSON.stringify({status:'error',completed_at:done,error:msg})}).catch(()=>{});return{ok:false,account_id:account.id,error:msg,transport:'composio'}}}
function sourceOauthState(uid,accountId,provider){const body=b64(JSON.stringify({uid,accountId,provider,exp:Math.floor(Date.now()/1000)+600}));return `${body}.${sign(`oauth:${body}`)}`}
function sourceReadOauthState(token){const i=String(token||'').lastIndexOf('.');if(i<1)return null;const body=token.slice(0,i),sig=token.slice(i+1);if(!secureEqual(sig,sign(`oauth:${body}`)))return null;try{const p=JSON.parse(unb64(body));if(!p.exp||p.exp<Math.floor(Date.now()/1000))return null;return p}catch{return null}}
function sourceCryptoKey(){if(!OAUTH_TOKEN_SECRET)throw new Error('OAuth token encryption is not configured');return scryptSync(OAUTH_TOKEN_SECRET,'concierge-source-sync-v1',32)}
function sourceEncrypt(v){const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',sourceCryptoKey(),iv),enc=Buffer.concat([cipher.update(String(v),'utf8'),cipher.final()]),tag=cipher.getAuthTag();return `v1.${iv.toString('base64url')}.${tag.toString('base64url')}.${enc.toString('base64url')}`}
function sourceDecrypt(v){const [ver,iv,tag,data]=String(v||'').split('.');if(ver!=='v1'||!iv||!tag||!data)throw new Error('Stored mailbox credential is invalid');const decipher=createDecipheriv('aes-256-gcm',sourceCryptoKey(),Buffer.from(iv,'base64url'));decipher.setAuthTag(Buffer.from(tag,'base64url'));return Buffer.concat([decipher.update(Buffer.from(data,'base64url')),decipher.final()]).toString('utf8')}
function sourceStripHtml(v){return String(v||'').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<br\s*\/?>/gi,'\n').replace(/<\/p>/gi,'\n').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/[ \t]+/g,' ').replace(/\n\s*\n\s*\n+/g,'\n\n').trim().slice(0,40000)}
function sourceB64UrlDecode(v){try{return Buffer.from(String(v||'').replace(/-/g,'+').replace(/_/g,'/'),'base64').toString('utf8')}catch{return''}}
function sourceGmailBody(payload){if(!payload)return'';if(payload.body?.data)return sourceB64UrlDecode(payload.body.data);const parts=payload.parts||[];const plain=parts.find(p=>p.mimeType==='text/plain'&&p.body?.data);if(plain)return sourceB64UrlDecode(plain.body.data);for(const p of parts){const nested=sourceGmailBody(p);if(nested)return p.mimeType==='text/html'?sourceStripHtml(nested):nested}return''}
function sourceHeader(headers,name){return (headers||[]).find(h=>String(h.name||'').toLowerCase()===name.toLowerCase())?.value||''}
function sourceParseSender(v){const s=String(v||''),m=s.match(/^(.*?)\s*<([^>]+)>$/);return m?{name:m[1].replace(/^"|"$/g,'').trim(),email:m[2].trim().toLowerCase()}:{name:'',email:s.trim().toLowerCase()}}
function sourceRedact(v){return String(v||'').replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'[EMAIL]').replace(/\+?\d[\d\s().-]{7,}\d/g,'[PHONE_OR_ID]').replace(/\b(?:USD|US\$|\$|EUR|GBP)\s?\d[\d,]*(?:\.\d+)?\b/gi,'[AMOUNT]').replace(/\b\d{7,}\b/g,'[ID]').slice(0,12000)}
function sourceJevCertainty(a){if(!a)return 0;if(typeof a.confidence==='number')return Math.max(0,Math.min(1,a.confidence));if(typeof a.noul==='number')return Math.max(0,Math.min(1,Math.abs(a.noul-.5)*2));return 0}
async function sourceJevClassify(message){if(!SOURCE_JEV_KEY)return null;const state={kind:'incoming_email',subject:sourceRedact(message.subject),sender:sourceRedact(message.sender_email),received_at:message.received_at,body:sourceRedact(message.body_text)};const questions={requires_action:{type:'noul',instructions:'Does this incoming email require the worker or a delegate to take an action rather than only monitor it?'},action_type:{type:'choice',instructions:'What is the best next work type?',criteria:{no_action:'Monitor only; no response or deliverable needed',draft_response:'Draft a reply or acknowledgement',generate_report:'Prepare a report, proposal, narrative, assessment or substantive deliverable',review_document:'Review or comment on a document',prepare_brief:'Prepare meeting or briefing material',update_tracker:'Update a tracker, spreadsheet or operational record',summarize_thread:'Summarize a thread or information set',clarify:'Ask for missing information or clarification',follow_up:'Follow up on a pending dependency',delegate_candidate:'Suitable to assign to another staff member'}},urgency:{type:'score',instructions:'How urgently does this email need attention?',criteria:['Can wait','Needs attention this week','Needs attention within 1-2 days','Needs attention today or is overdue/critical']},human_approval_needed:{type:'noul',instructions:'Does an authorized human need to approve the resulting external action, communication, financial step, beneficiary decision, or consequential output before it is final?'}};try{const r=await fetch('https://api.typesafe.ai/v1/systemone',{method:'POST',headers:{authorization:`Bearer ${SOURCE_JEV_KEY}`,'content-type':'application/json',accept:'application/json'},body:JSON.stringify({state,model:SOURCE_JEV_MODEL,questions})});const data=await r.json().catch(()=>({}));if(!r.ok)return null;const vals=Object.values(data.answers||{}),confidence=vals.length?vals.map(sourceJevCertainty).reduce((a,b)=>a+b,0)/vals.length:0;return{answers:data.answers||{},confidence:Number(confidence.toFixed(4)),model:data.model||SOURCE_JEV_MODEL}}catch{return null}}
async function sourceAnalyzeEmail(message,projects){if(!OPENAI_API_KEY)return{summary:String(message.body_text||'').slice(0,700),due_at:null,project_hint:null};try{const projectNames=(projects||[]).map(p=>({name:p.name,code:p.code,aliases:p.aliases||[]}));const resp=await openaiResponse({developer:'Extract operational facts from an incoming humanitarian-work email. Do not invent. Return JSON only with summary (max 3 sentences), due_at (ISO 8601 only when the email states an explicit unambiguous deadline, otherwise null), and project_hint (one exact project name/code from the supplied list only when supported, otherwise null).',userContent:`PROJECTS\n${JSON.stringify(projectNames)}\n\nEMAIL SUBJECT\n${message.subject||''}\n\nEMAIL BODY\n${String(message.body_text||'').slice(0,18000)}`,maxOutput:700});const x=parseModelJson(outputText(resp));return{summary:clean(x.summary||message.body_text,1800),due_at:x.due_at&&Number.isFinite(Date.parse(x.due_at))?new Date(x.due_at).toISOString():null,project_hint:clean(x.project_hint,200)||null}}catch{return{summary:String(message.body_text||'').slice(0,700),due_at:null,project_hint:null}}}
function sourceMatchProject(message,projects,hint){const h=String(hint||'').toLowerCase();if(h){const exact=(projects||[]).find(p=>[p.name,p.code,...(p.aliases||[])].filter(Boolean).some(v=>String(v).toLowerCase()===h));if(exact)return exact}const text=`${message.subject||''} ${message.body_text||''}`.toLowerCase();let best=null,bestScore=0;for(const p of projects||[]){let score=0;for(const v of [p.name,p.code,...(p.aliases||[])].filter(Boolean)){const s=String(v).trim().toLowerCase();if(s.length>=3&&text.includes(s))score+=s===String(p.code||'').toLowerCase()?3:2}if(score>bestScore){best=p;bestScore=score}}return bestScore?best:null}
async function sourceRefreshAccess(account,cred){const refresh=sourceDecrypt(cred.refresh_token_enc);if(account.provider==='gmail'){const body=new URLSearchParams({client_id:GOOGLE_CLIENT_ID,client_secret:GOOGLE_CLIENT_SECRET,refresh_token:refresh,grant_type:'refresh_token'});const r=await fetch('https://oauth2.googleapis.com/token',{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error_description||d.error||`Google token ${r.status}`);return d.access_token}if(account.provider==='outlook'){const body=new URLSearchParams({client_id:MICROSOFT_CLIENT_ID,client_secret:MICROSOFT_CLIENT_SECRET,refresh_token:refresh,grant_type:'refresh_token',scope:'openid profile email offline_access https://graph.microsoft.com/Mail.Read'});const r=await fetch('https://login.microsoftonline.com/common/oauth2/v2.0/token',{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error_description||d.error||`Microsoft token ${r.status}`);if(d.refresh_token&&d.refresh_token!==refresh)await sb(`concierge_email_credentials?account_id=eq.${account.id}`,{method:'PATCH',body:JSON.stringify({refresh_token_enc:sourceEncrypt(d.refresh_token),token_expires_at:new Date(Date.now()+Number(d.expires_in||3600)*1000).toISOString(),updated_at:now()})});return d.access_token}throw new Error('Unsupported provider')}
function sourceOperationallyRelevant(message){
  const sender=String(message?.sender_email||'').trim().toLowerCase();
  const subject=String(message?.subject||'').toLowerCase();
  const body=String(message?.body_text||'').toLowerCase();
  const text=`${subject} ${body}`;
  const domain=sender.includes('@')?sender.split('@').pop():sender;
  const blockedDomains=['email.apple.com','accounts.google.com','microsoftrewards.com','linkedin.com','alison.com','academia-mail.com','udemy.com','eldtraining.com','impactpool.org','learn.inasp.info','umd.edu'];
  const negative=/\b(billing problem|security alert|sale starts|sale ends|bonus points|subscription confirmed|course is ready|start learning|certificate holders|popular in your network|mentioned in .* papers|weekly:|newsletter|unsubscribe|promotional|special offer|limited time|career growth|job alert)\b/i.test(text);
  const workDomains=['nrc.no','iom.int','fao.org','wfp.org','unicef.org','unhcr.org','unocha.org','ocha.org','undp.org','who.int','icrc.org','ifrc.org','drc.ngo','rescue.org','savethechildren.net','savethechildren.org','mercycorps.org','care.org','oxfam.org','acted.org','worldvision.org','unops.org','unwomen.org'];
  const strongWork=/\b(food security|livelihoods?|fsl|beneficiar(?:y|ies)|distribution|cash transfer|cash assistance|voucher|field report|site report|situation report|sitrep|workplan|work plan|implementation update|project implementation|project report|monthly report|weekly report|donor report|proposal|budget revision|procurement|logistics|monitoring|indicator|baseline|endline|assessment|stakeholder|site visit|humanitarian|emergency response|emergency trend|dtm|cluster meeting|meeting minutes|activity report|field team)\b/i.test(text);
  if(blockedDomains.some(d=>domain===d||domain.endsWith('.'+d)))return false;
  if(negative&&!strongWork)return false;
  if(workDomains.some(d=>domain===d||domain.endsWith('.'+d)))return true;
  return strongWork;
}
async function sourceShouldIngest(uid,message){
  const sender=String(message?.sender_email||'').trim().toLowerCase();
  try{
    const [projects,trusted]=await Promise.all([
      sb(`humanitarian_projects?select=id,name,code,aliases,status&user_id=eq.${uid}&status=neq.archived`),
      sb(`fsl_concierge_email_sources?select=email,is_active&user_id=eq.${uid}&is_active=eq.true&limit=200`)
    ]);
    if((trusted||[]).some(x=>String(x.email||'').trim().toLowerCase()===sender))return true;
    if(sourceMatchProject(message,projects||[],null))return true;
  }catch{}
  return sourceOperationallyRelevant(message);
}
